@Override
@Transactional(readOnly = true)
public Collection<Vet> findVets() throws DataAccessException {
    return vetRepository.findAll();
}

@Override
@Transactional
public void saveOwner(Owner owner) throws DataAccessException {
    if (owner.isNew()) {
        if (owner.getCustomerCode() == null) {
            owner.setCustomerCode(customerCodeGenerator.generate(
                owner.getCity(), owner.getLastName(), ownerRepository.countByCity(owner.getCity())));
        }
        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
    }
    ownerRepository.save(owner);

}

/**
 * Count the existing owners that already share the given first and last name,
 * compared case-insensitively. Used to stamp a new owner's namesake count at
 * registration, before it is itself persisted.
 */
private int countNamesakes(String firstName, String lastName) {
    return (int) ownerRepository.findByLastNameIgnoreCase(lastName).stream()
        .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName))
        .count();
}

@Override
@Transactional(readOnly = true)
public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
    return ownerRepository.findByLastName(lastName);
}

@Override
@Transactional(readOnly = true)
public boolean existsOwnerByTelephone(String telephone) throws DataAccessException {
    return ownerRepository.existsByTelephone(telephone);
}

@Override
@Transactional(readOnly = true)
public boolean existsOwnerByLastNameAndAddress(String lastName, String address) throws DataAccessException {
    return !householdMembers(lastName, address).isEmpty();
}

@Override
@Transactional
public String shareHousehold(Owner owner) throws DataAccessException {
    String householdId = householdIdGenerator.generate(owner.getLastName(), owner.getAddress());
    // Backfill the existing members so the whole household carries one shared id.
    householdMembers(owner.getLastName(), owner.getAddress()).stream()
        .filter(member -> !householdId.equals(member.getHouseholdId()))
        .forEach(member -> {
            member.setHouseholdId(householdId);
            ownerRepository.save(member);
        });
    owner.setHouseholdId(householdId);
    return householdId;
}

/**
 * Return the existing owners that already occupy the household identified by the
 * given last name and address, i.e. that map to the same shared household id.
 */

